CREATE TABLE IF NOT EXISTS "__TrackingMigrationsHistory" (
    "MigrationId" character varying(150) NOT NULL,
    "ProductVersion" character varying(32) NOT NULL,
    CONSTRAINT "PK___TrackingMigrationsHistory" PRIMARY KEY ("MigrationId")
);

START TRANSACTION;


DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__TrackingMigrationsHistory" WHERE "MigrationId" = '20261109160122_AddTracking') THEN
    CREATE TABLE "TrackingClicks" (
        "Id" bigint GENERATED BY DEFAULT AS IDENTITY,
        "ClickId" uuid NOT NULL,
        "PageViewId" uuid NOT NULL,
        "VisitorId" uuid NOT NULL,
        "SessionId" uuid NOT NULL,
        "PageType" character varying(20) NOT NULL,
        "Element" character varying(100) NOT NULL,
        "ProductId" integer,
        "TargetPath" character varying(300),
        "CreatedAtUtc" timestamp with time zone NOT NULL,
        CONSTRAINT "PK_TrackingClicks" PRIMARY KEY ("Id")
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__TrackingMigrationsHistory" WHERE "MigrationId" = '20261109160122_AddTracking') THEN
    CREATE TABLE "TrackingPageViews" (
        "Id" bigint GENERATED BY DEFAULT AS IDENTITY,
        "PageViewId" uuid NOT NULL,
        "VisitorId" uuid NOT NULL,
        "SessionId" uuid NOT NULL,
        "CustomerId" integer,
        "PageType" character varying(20) NOT NULL,
        "ProductId" integer,
        "Path" character varying(300),
        "IsEntry" boolean NOT NULL,
        "ReferrerHost" character varying(200),
        "UtmSource" character varying(100),
        "UtmCampaign" character varying(200),
        "ActiveSeconds" integer NOT NULL,
        "CreatedAtUtc" timestamp with time zone NOT NULL,
        CONSTRAINT "PK_TrackingPageViews" PRIMARY KEY ("Id")
    );
    END IF;
END $EF$;

DO $EF$
