        "CustomerId" integer,
        "ContactName" character varying(150),
        "ContactPhone" character varying(30),
        "ContactEmail" character varying(200),
        "FirstUtmSource" character varying(100),
        "FirstUtmMedium" character varying(100),
        "FirstUtmCampaign" character varying(200),
        "FirstSeenUtc" timestamp with time zone NOT NULL,
        "LastSeenUtc" timestamp with time zone NOT NULL,
        CONSTRAINT "PK_TrackingVisitors" PRIMARY KEY ("VisitorId")
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__TrackingMigrationsHistory" WHERE "MigrationId" = '20261109160122_AddTracking') THEN
    CREATE TABLE "TrackingEvents" (
        "Id" bigint GENERATED BY DEFAULT AS IDENTITY,
        "EventId" uuid NOT NULL,
        "EventType" character varying(32) NOT NULL,
        "VisitorId" uuid NOT NULL,
        "CustomerId" integer,
        "SessionId" uuid,
        "CheckoutToken" uuid,
        "OrderId" integer,
        "SupersededAtUtc" timestamp with time zone,
        "TotalValue" numeric(18,2) NOT NULL,
        "ItemCount" integer NOT NULL,
        "PageUrl" character varying(500),
        "UtmSource" character varying(100),
        "UtmMedium" character varying(100),
        "UtmCampaign" character varying(200),
        "Fbclid" character varying(500),
        "CreatedAtUtc" timestamp with time zone NOT NULL,
        CONSTRAINT "PK_TrackingEvents" PRIMARY KEY ("Id"),
        CONSTRAINT "FK_TrackingEvents_TrackingVisitors_VisitorId" FOREIGN KEY ("VisitorId") REFERENCES "TrackingVisitors" ("VisitorId") ON DELETE CASCADE
    );
    END IF;
END $EF$;

